import { fn } from "arktype";

export const add = fn("number", "number", ":", "number")(
  (a: number, b: number): number => a + b,
);

export const subtract = fn("number", "number", ":", "number")(
  (a: number, b: number): number => a - b,
);

export const multiply = fn("number", "number", ":", "number")(
  (a: number, b: number): number => a * b,
);

// divide must reject any divisor equal to 0
export const divide = fn("number", "number!=0", ":", "number")(
  (a: number, b: number): number => a / b,
);

// modulo must reject any divisor that is not a non-zero integer
// number%1==0 ensures integer, number!=0 ensures non-zero
export const modulo = fn("number", "number%1==0 & number!=0", ":", "number")(
  (a: number, b: number): number => a % b,
);

export const operations = {
  add,
  subtract,
  multiply,
  divide,
  modulo,
} as const;

export type OpName = keyof typeof operations;

import { fn, TraversalError } from "arktype";
import { operations } from "./operations.js";

const compute = fn(
  "'add'|'subtract'|'multiply'|'divide'|'modulo'",
  "number",
  "number",
  ":",
  "number",
)((op: "add" | "subtract" | "multiply" | "divide" | "modulo", a: number, b: number): number => {
  return operations[op](a, b);
});

async function main(): Promise<void> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(Buffer.from(chunk));
  }

  const input = Buffer.concat(chunks).toString("utf-8").trim();
  if (!input) {
    process.exit(0);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(input);
  } catch {
    // If JSON parsing fails, it will fail at the type.fn boundary
    try {
      compute(parsed as never, undefined as never, undefined as never);
    } catch (err) {
      if (err instanceof TraversalError) {
        console.log(`ERR ${err.message}`);
        process.exit(0);
      }
      throw err;
    }
    process.exit(0);
  }

  const { op, a, b } = parsed as { op: string; a: number; b: number };

  try {
    const result = compute(op, a, b);
    console.log(`OK ${String(result)}`);
  } catch (err) {
    if (err instanceof TraversalError) {
      console.log(`ERR ${err.message}`);
    } else {
      throw err;
    }
  }

  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

